function getVoiceParams(languageCode = "en-US", voiceOption = "neutral") {
    const lang = typeof languageCode === "string" ? languageCode : "en-US";
    const normalized = voiceOption ? String(voiceOption).toLowerCase() : "neutral";
    const exact = VOICE_MAP[lang];
    const base = lang.split("-")[0] ? `${lang.split("-")[0]}` : null;
    const baseMap = base ? VOICE_MAP[base] : null;
    const fallback = VOICE_MAP["en-US"];
    const map = exact || baseMap || fallback;
    const voiceEntry = map[normalized] || map["neutral"] || fallback["neutral"];
    return {
        voiceName: voiceEntry.name,
        ssmlGender: voiceEntry.ssmlGender
    };
}
